private _filter(entry: Entry, patterns: PatternsRegexSet): boolean {
	const filepath = utils.path.removeLeadingDotSegment(entry.path);

	if (this._settings.unique && this._isDuplicateEntry(filepath)) {
		return false;
	}

	if (this._settings.filter !== undefined && !this._settings.filter(entry)) {
		return false;
	}

	if (this._onlyFileFilter(entry) || this._onlyDirectoryFilter(entry)) {
		return false;
	}

	const isMatched = this._isMatchToPatternsSet(filepath, patterns, entry.dirent.isDirectory());
	if (!isMatched) {
		return false;
	}

	if (this._settings.unique) {
		this._createIndexRecord(filepath);
	}

	return isMatched;
}

private _isDuplicateEntry(filepath: string): boolean {
	return this.index.has(filepath);
}

private _filter(basePath: string, entry: Entry, matcher: PartialMatcher, negativeRe: PatternRe[]): boolean {
	if (this._isSkippedByDeep(basePath, entry.path)) {
		return false;
	}

	if (this._isSkippedSymbolicLink(entry)) {
		return false;
