	const filepath = utils.path.removeLeadingDotSegment(entry.path);

	if (this._isSkippedByPositivePatterns(filepath, matcher)) {
		return false;
	}

	if (!this._isSkippedByNegativePatterns(filepath, negativeRe)) {
		return false;
	}

