      const merge = doc.createPair('<<', doc.createAlias(a))
      b.items.push(merge)
      expect(doc.toJS()).toMatchObject([{ a: 'A' }, { a: 'A', b: 'B' }])
      expect(String(doc)).toBe('[ &a1 { a: A }, { b: B, <<: *a1 } ]\n')
    })

    test('using customTags:["merge"]', () => {
      const doc = parseDocument<YAMLSeq<YAMLMap>, false>(
        '[{ a: A }, { b: B }]',
